PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL, code TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, name TEXT NOT NULL, phone TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','management','officer')), password_hash TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, zone_id TEXT, subzone_id TEXT, area_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(org_id, phone), FOREIGN KEY(org_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, expires_at INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS zones (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, name TEXT NOT NULL, boundary_json TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(org_id,name));
CREATE TABLE IF NOT EXISTS subzones (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, zone_id TEXT NOT NULL, name TEXT NOT NULL, boundary_json TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(org_id,zone_id,name), FOREIGN KEY(zone_id) REFERENCES zones(id));
CREATE TABLE IF NOT EXISTS areas (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, subzone_id TEXT NOT NULL, name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(org_id,subzone_id,name), FOREIGN KEY(subzone_id) REFERENCES subzones(id));
CREATE TABLE IF NOT EXISTS streets (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, subzone_id TEXT NOT NULL, street_no TEXT NOT NULL, street_name TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(org_id,subzone_id,street_no), FOREIGN KEY(subzone_id) REFERENCES subzones(id));
CREATE TABLE IF NOT EXISTS consumers (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, consumer_no TEXT NOT NULL, name TEXT, address TEXT, zone_id TEXT, subzone_id TEXT, area_id TEXT, street_id TEXT, lat REAL, lng REAL, gps_accuracy REAL, source TEXT NOT NULL DEFAULT 'import', updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(org_id,consumer_no));
CREATE TABLE IF NOT EXISTS activities (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, consumer_no TEXT, officer_id TEXT NOT NULL, officer_name TEXT, officer_phone TEXT, activity_type TEXT NOT NULL, activity_json TEXT NOT NULL DEFAULT '{}', lat REAL, lng REAL, gps_accuracy REAL, occurred_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, zone_id TEXT, subzone_id TEXT, area_id TEXT, street_id TEXT, FOREIGN KEY(officer_id) REFERENCES users(id));
CREATE INDEX IF NOT EXISTS idx_activities_org_time ON activities(org_id, occurred_at);
CREATE INDEX IF NOT EXISTS idx_activities_consumer ON activities(org_id, consumer_no);
CREATE TABLE IF NOT EXISTS officer_live_current (org_id TEXT NOT NULL, officer_id TEXT NOT NULL, lat REAL NOT NULL, lng REAL NOT NULL, accuracy REAL, speed REAL, heading REAL, recorded_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'online', PRIMARY KEY(org_id,officer_id));
CREATE TABLE IF NOT EXISTS officer_live_history (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, officer_id TEXT NOT NULL, lat REAL NOT NULL, lng REAL NOT NULL, accuracy REAL, speed REAL, heading REAL, recorded_at TEXT NOT NULL, event_type TEXT NOT NULL DEFAULT 'point');
CREATE INDEX IF NOT EXISTS idx_live_history_officer_time ON officer_live_history(org_id,officer_id,recorded_at);
CREATE TABLE IF NOT EXISTS files (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, owner_id TEXT NOT NULL, r2_key TEXT NOT NULL, content_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS activity_colors (id INTEGER PRIMARY KEY AUTOINCREMENT, org_id TEXT NOT NULL, activity_type TEXT NOT NULL, color_hex TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(org_id,activity_type));
CREATE TABLE IF NOT EXISTS wasaTargets (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, officer_id TEXT NOT NULL, sectionKey TEXT NOT NULL, targetCount INTEGER NOT NULL, areaFilter TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(officer_id) REFERENCES users(id), UNIQUE(org_id,officer_id,sectionKey));
CREATE TABLE IF NOT EXISTS wasaNotifications (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, event_type TEXT NOT NULL, to TEXT NOT NULL, vars JSON DEFAULT '{}', link JSON DEFAULT '{}', by TEXT, ts INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS wasaAudit (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, type TEXT NOT NULL, byName TEXT, byPhone TEXT, byRole TEXT, ts INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS wasaProfileRequests (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, officerId TEXT NOT NULL, officerPhone TEXT NOT NULL, changes JSON NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS wasaMessages (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, officerPhone TEXT NOT NULL, officerName TEXT, senderRole TEXT NOT NULL, senderName TEXT, text TEXT NOT NULL, createdAt INTEGER NOT NULL DEFAULT (CAST(strftime('%s','now') AS INTEGER)), readByAdmin INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS wasaPasswordResets (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, userId TEXT NOT NULL, phone TEXT NOT NULL, requestedNewPass TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS wasaConsumerChunks (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, chunkId TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, json TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS wasaConsumerMeta (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, chunkCount INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_activities_org_consumer ON activities(org_id, consumer_no);
CREATE INDEX IF NOT EXISTS idx_users_org_role ON users(org_id, role);
CREATE INDEX IF NOT EXISTS idx_consumers_org_zone ON consumers(org_id, zone_id);
CREATE INDEX IF NOT EXISTS idx_consumers_org_subzone ON consumers(org_id, subzone_id);
CREATE INDEX IF NOT EXISTS idx_activities_officer ON activities(org_id, officer_id);